(2964216, 416919, 65035, '<td valign="top">I like that vertical milky effect with the bokeh.</td>', 'I like that vertical milky effect with the bokeh.', '2006-10-26 03:49:52.000000', NULL, 1),
(2964221, 416119, 65035, '<td valign="top">This is very dramatic, I like tke the combination of streaks and big circles in the bokeh. A lovely frame also.</td>', 'This is very dramatic, I like tke the combination of streaks and big circles in the bokeh. A lovely frame also.', '2006-10-26 03:51:41.000000', NULL, 1),
