INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2965730, 414667, 43565, '<td valign="top">I find the division between the leaves on the left and the background on the right distracting.</td>', 'I find the division between the leaves on the left and the background on the right distracting.', '2006-10-26 17:52:13.000000', NULL, 1),
(2965733, 414048, 43565, '<td valign="top">I wish there was more detail in the orchid.</td>', 'I wish there was more detail in the orchid.', '2006-10-26 17:52:44.000000', NULL, 1),
(2965755, 413875, 46819, '<td valign="top">I''d prefer it if the circle hadn''t circled other words... however, I really like the idea, the b&amp;w is certainly effective, and it''s exactly what I think the challenge asked for. Very nicely done, 9 for me.</td>', 'I''d prefer it if the circle hadn''t circled other words... however, I really like the idea, the b&w is certainly effective, and it''s exactly what I think the challenge asked for. Very nicely done, 9 for me.', '2006-10-26 18:03:03.000000', NULL, 1),
(2965757, 416438, 43565, '<td valign="top">I think some part of the shot should be in focus.</td>', 'I think some part of the shot should be in focus.', '2006-10-26 18:03:31.000000', NULL, 1),
(2965770, 416979, 52336, '<td valign="top">There really is no bokeh here.  Even loosely defined, bokeh suggests an out of focus area, and this picture is in focus front to back, from what I can tell.  Maybe focusing more closely on the sign while making the men in back more blurry would have helped, because the setup is interesting.</td>', 'There really is no bokeh here.  Even loosely defined, bokeh suggests an out of focus area, and this picture is in focus front to back, from what I can tell.  Maybe focusing more closely on the sign while making the men in back more blurry would have helped, because the setup is interesting.', '2006-10-26 18:11:10.000000', NULL, 1),
(2965771, 414619, 52336, '<td valign="top">Kinda lazy, no? :)</td>', 'Kinda lazy, no? :)', '2006-10-26 18:11:46.000000', NULL, 1),
(2965773, 415932, 52336, '<td valign="top">Very lovely, goregous composition, and wonderful capture.  I love the subtle and colourful bokeh.</td>', 'Very lovely, goregous composition, and wonderful capture.  I love the subtle and colourful bokeh.', '2006-10-26 18:13:04.000000', NULL, 1),
(2965775, 415786, 43565, '<td valign="top">I would like this better if the leaves were more in focus.</td>', 'I would like this better if the leaves were more in focus.', '2006-10-26 18:14:28.000000', NULL, 1),
(2965780, 416493, 36382, '<td valign="top">This is a beautiful photo with beautiful light and colors in the background.  The bright light top middle is a little distracting.</td>', 'This is a beautiful photo with beautiful light and colors in the background.  The bright light top middle is a little distracting.', '2006-10-26 18:18:05.000000', NULL, 1),
(2965786, 416956, 61125, '<td valign="top">great image, but the title takes away from the chaos of the scene..  businessmen/women regrouping on the street and and looking very stressed..</td>', 'great image, but the title takes away from the chaos of the scene..  businessmen/women regrouping on the street and and looking very stressed..', '2006-10-26 18:21:59.000000', NULL, 1),
(2965788, 416893, 61125, '<td valign="top">a little too saturated..</td>', 'a little too saturated..', '2006-10-26 18:22:57.000000', NULL, 1),
(2965792, 415900, 61125, '<td valign="top">another title i would rather have not followed such a nice picture..</td>', 'another title i would rather have not followed such a nice picture..', '2006-10-26 18:23:53.000000', NULL, 1),
(2965793, 415234, 61125, '<td valign="top">very nice</td>', 'very nice', '2006-10-26 18:24:19.000000', NULL, 1),
(2965796, 416139, 61125, '<td valign="top">great color cast!</td>', 'great color cast!', '2006-10-26 18:24:48.000000', NULL, 1),
(2965813, 416401, 36382, '<td valign="top">I like this but it doesn''t feel like a photograph.</td>', 'I like this but it doesn''t feel like a photograph.', '2006-10-26 18:30:49.000000', NULL, 1),
(2965833, 413515, 43565, '<td valign="top">It looks like you needed a tripod.</td>', 'It looks like you needed a tripod.', '2006-10-26 18:39:41.000000', NULL, 1),
(2965840, 414648, 43565, '<td valign="top">Good for an anti-smoking campaign.</td>', 'Good for an anti-smoking campaign.', '2006-10-26 18:41:16.000000', NULL, 1),
(2965844, 416891, 12733, '<td valign="top">Great capture. I notice the bird is banded. Is it tame?</td>', 'Great capture. I notice the bird is banded. Is it tame?', '2006-10-26 18:41:35.000000', NULL, 1),
(2965848, 416112, 12733, '<td valign="top">Too much bokeh relative to the flowers. And the flowers are too dark to stand out.</td>', 'Too much bokeh relative to the flowers. And the flowers are too dark to stand out.', '2006-10-26 18:43:44.000000', NULL, 1),
(2965849, 416833, 12733, '<td valign="top">Very cute, nice capture.</td>', 'Very cute, nice capture.', '2006-10-26 18:44:16.000000', NULL, 1),
(2965853, 415178, 23430, '<td valign="top">Not strong on bokeh but it''s an awesome capture. Well done. I like how each bird has a different wing position.</td>', 'Not strong on bokeh but it''s an awesome capture. Well done. I like how each bird has a different wing position.', '2006-10-26 18:45:42.000000', NULL, 1),
(2965854, 416217, 12733, '<td valign="top">This is a nicely composed and exposed picture, but I think the background is too close to being in focus to be bokeh.</td>', 'This is a nicely composed and exposed picture, but I think the background is too close to being in focus to be bokeh.', '2006-10-26 18:46:18.000000', NULL, 1),
(2965855, 415781, 12733, '<td valign="top">Very clever, and well photographed.</td>', 'Very clever, and well photographed.', '2006-10-26 18:46:44.000000', NULL, 1),
(2965856, 416725, 23430, '<td valign="top">Nice and crisp and nice lighting. Background looks good too.</td>', 'Nice and crisp and nice lighting. Background looks good too.', '2006-10-26 18:47:05.000000', NULL, 1),
(2965857, 416752, 5792, '<td valign="top">I''m guessing that you are being trashed for using motion blur to produce bokeh. The guy that invented the term ''bokeh'' as applied to photography specifically excluded motion blur and camera shake in his definition, I believe. Yours is a good picture under any definition.</td>', 'I''m guessing that you are being trashed for using motion blur to produce bokeh. The guy that invented the term ''bokeh'' as applied to photography specifically excluded motion blur and camera shake in his definition, I believe. Yours is a good picture under any definition.', '2006-10-26 18:47:52.000000', NULL, 1),
(2965858, 416889, 12733, '<td valign="top">Great combination of colors!</td>', 'Great combination of colors!', '2006-10-26 18:47:57.000000', NULL, 1),
(2965860, 415953, 12733, '<td valign="top">Spooky spider, but what''s the background?</td>', 'Spooky spider, but what''s the background?', '2006-10-26 18:48:34.000000', NULL, 1),
