(2979114, 416800, 23430, '<td valign="top">Fantastic shot. Well done.</td>', 'Fantastic shot. Well done.', '2006-10-31 15:40:52.000000', NULL, 1),
(2979132, 416948, 3746, '<td valign="top">I like the bokeh of the smoke/fog, but the foreground subjects dint really float my boat. 6</td>', 'I like the bokeh of the smoke/fog, but the foreground subjects dint really float my boat. 6', '2006-10-31 15:47:32.000000', NULL, 1),
(2979134, 416819, 3746, '<td valign="top">nice and sharp foreground, nice creamy background. 7</td>', 'nice and sharp foreground, nice creamy background. 7', '2006-10-31 15:47:51.000000', NULL, 1),
